<?php
require_once '../config/db.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../index.php');$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
 if(isset($_POST['save_type'])){$name=trim((string)$_POST['type_name']);$kind=in_array($_POST['base_kind'],['customer','vendor','both'],true)?$_POST['base_kind']:'customer';$typeId=(int)($_POST['type_id']??0);if($name==='')throw new RuntimeException('Type name is required.');if($typeId){$pdo->prepare('UPDATE contact_types SET name=?,base_kind=? WHERE id=?')->execute([$name,$kind,$typeId]);}else{$pdo->prepare('INSERT INTO contact_types(name,base_kind) VALUES(?,?)')->execute([$name,$kind]);}redirect('contacts.php?saved=type');}
 if(isset($_POST['delete_type'])){$typeId=(int)$_POST['type_id'];$used=$pdo->prepare('SELECT COUNT(*) FROM contacts WHERE contact_type_id=?');$used->execute([$typeId]);if($used->fetchColumn())throw new RuntimeException('This type is assigned to contacts. Reassign them before deleting it.');$pdo->prepare('DELETE FROM contact_types WHERE id=?')->execute([$typeId]);redirect('contacts.php?saved=type');}
 if(isset($_POST['save_contact'])){$id=(int)($_POST['contact_id']??0);$typeId=(int)$_POST['contact_type_id'];$s=$pdo->prepare('SELECT base_kind FROM contact_types WHERE id=? AND is_active=1');$s->execute([$typeId]);$kind=$s->fetchColumn();if(!$kind)throw new RuntimeException('Choose a valid contact type.');$values=[$kind,$typeId,trim((string)$_POST['company_name']),trim((string)$_POST['contact_person']),trim((string)$_POST['email']),trim((string)$_POST['phone']),trim((string)$_POST['billing_address']),trim((string)$_POST['tax_id_number']),$_POST['currency_code']];if($values[2]==='')throw new RuntimeException('Display name is required.');if($id){$pdo->prepare('UPDATE contacts SET contact_type=?,contact_type_id=?,company_name=?,contact_person=?,email=?,phone=?,billing_address=?,tax_id_number=?,currency_code=? WHERE id=?')->execute([...$values,$id]);}else{$pdo->prepare('INSERT INTO contacts(contact_type,contact_type_id,company_name,contact_person,email,phone,billing_address,tax_id_number,currency_code) VALUES(?,?,?,?,?,?,?,?,?)')->execute($values);}redirect('contacts.php?saved=contact');}
 }}catch(Throwable $e){$error=$e instanceof PDOException&&$e->getCode()==='23000'?'That type name already exists.':$e->getMessage();}
$editId=(int)($_GET['edit']??0);$edit=[];if($editId){$s=$pdo->prepare('SELECT * FROM contacts WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:[];}$types=$pdo->query('SELECT * FROM contact_types WHERE is_active=1 ORDER BY base_kind,name')->fetchAll();$currencies=$pdo->query('SELECT code,name,symbol FROM currencies ORDER BY is_base_currency DESC,name')->fetchAll();$filterType=(int)($_GET['type']??0);$q=trim((string)($_GET['q']??''));$where=[];$params=[];if($filterType){$where[]='c.contact_type_id=?';$params[]=$filterType;}if($q!==''){$where[]='(c.company_name LIKE ? OR c.contact_person LIKE ? OR c.email LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}$sql='SELECT c.*,COALESCE(t.name,CONCAT(UCASE(LEFT(c.contact_type,1)),SUBSTRING(c.contact_type,2))) type_name,t.base_kind,cur.symbol FROM contacts c LEFT JOIN contact_types t ON t.id=c.contact_type_id LEFT JOIN currencies cur ON cur.code=c.currency_code'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY c.company_name';$s=$pdo->prepare($sql);$s->execute($params);$contacts=$s->fetchAll();require_once 'includes/header.php';require_once 'includes/sidebar.php';$input='mt-1 w-full border rounded-lg px-3 py-2.5';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center gap-4 sticky top-0 z-10"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Customers & vendors</h2><p class="text-sm text-slate-500">Create custom contact types and edit every contact</p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if($error):?><div class="bg-rose-50 border border-rose-200 text-rose-800 p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border border-emerald-200 text-emerald-800 p-4 rounded-xl mb-5">Changes saved.</div><?php endif;?>
<div class="grid xl:grid-cols-3 gap-7"><div class="space-y-6"><form method="post" class="bg-white border rounded-2xl p-6 space-y-4"><?=csrf_field()?><input type="hidden" name="contact_id" value="<?=h((string)$editId)?>"><div><h3 class="font-bold text-lg"><?=$editId?'Edit contact':'Add contact'?></h3><p class="text-sm text-slate-500">Type and currency can be changed later.</p></div><label class="block text-sm">Contact type<select name="contact_type_id" required class="<?=$input?> bg-white"><?php foreach($types as $t):?><option value="<?=$t['id']?>" <?=($edit['contact_type_id']??0)==$t['id']?'selected':''?>><?=h($t['name'])?> · <?=h($t['base_kind'])?></option><?php endforeach;?></select></label><label class="block text-sm">Company / display name<input name="company_name" required value="<?=h($edit['company_name']??'')?>" class="<?=$input?>"></label><label class="block text-sm">Contact person<input name="contact_person" value="<?=h($edit['contact_person']??'')?>" class="<?=$input?>"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm">Email<input type="email" name="email" value="<?=h($edit['email']??'')?>" class="<?=$input?>"></label><label class="text-sm">Phone<input name="phone" value="<?=h($edit['phone']??'')?>" class="<?=$input?>"></label></div><div class="grid grid-cols-2 gap-3"><label class="text-sm">Tax ID<input name="tax_id_number" value="<?=h($edit['tax_id_number']??'')?>" class="<?=$input?>"></label><label class="text-sm">Currency<select name="currency_code" class="<?=$input?> bg-white"><?php foreach($currencies as $c):?><option value="<?=$c['code']?>" <?=($edit['currency_code']??setting($pdo,'base_currency','USD'))===$c['code']?'selected':''?>><?=h($c['code'].' · '.$c['name'])?></option><?php endforeach;?></select></label></div><label class="block text-sm">Billing address<textarea name="billing_address" rows="2" class="<?=$input?>"><?=h($edit['billing_address']??'')?></textarea></label><div class="flex gap-2"><button name="save_contact" class="brand-bg text-white px-5 py-2.5 rounded-lg font-semibold flex-1"><?=$editId?'Update':'Save'?> contact</button><?php if($editId):?><a href="contacts.php" class="border px-4 py-2.5 rounded-lg">Cancel</a><?php endif;?></div></form>
<section class="bg-white border rounded-2xl p-6"><h3 class="font-bold text-lg">Custom contact types</h3><p class="text-sm text-slate-500 mb-4">The accounting role controls customer/vendor behavior.</p><form method="post" class="grid grid-cols-2 gap-2 mb-4"><?=csrf_field()?><input name="type_name" placeholder="e.g. Retail customer" required class="border rounded-lg px-3 py-2"><select name="base_kind" class="border rounded-lg px-3 py-2 bg-white"><option value="customer">Customer role</option><option value="vendor">Vendor role</option><option value="both">Both roles</option></select><button name="save_type" class="col-span-2 bg-slate-900 text-white rounded-lg px-4 py-2">Create type</button></form><div class="space-y-2"><?php foreach($types as $t):?><details class="border rounded-lg p-3"><summary class="cursor-pointer text-sm font-semibold"><?=h($t['name'])?> <span class="text-slate-400">· <?=h($t['base_kind'])?></span></summary><form method="post" class="grid grid-cols-2 gap-2 mt-3"><?=csrf_field()?><input type="hidden" name="type_id" value="<?=$t['id']?>"><input name="type_name" value="<?=h($t['name'])?>" class="border rounded px-2 py-1"><select name="base_kind" class="border rounded px-2 py-1"><?php foreach(['customer','vendor','both'] as $k):?><option <?=$t['base_kind']===$k?'selected':''?>><?=$k?></option><?php endforeach;?></select><button name="save_type" class="bg-slate-900 text-white rounded py-1">Update</button><button name="delete_type" onclick="return confirm('Delete this unused type?')" class="border border-rose-200 text-rose-700 rounded py-1">Delete</button></form></details><?php endforeach;?></div></section></div>
<section class="xl:col-span-2 bg-white border rounded-2xl overflow-hidden h-fit"><form class="p-4 border-b flex gap-3"><input name="q" value="<?=h($q)?>" placeholder="Search contacts" class="border rounded-lg px-3 py-2 flex-1"><select name="type" class="border rounded-lg px-3 py-2 bg-white"><option value="">All types</option><?php foreach($types as $t):?><option value="<?=$t['id']?>" <?=$filterType===$t['id']?'selected':''?>><?=h($t['name'])?></option><?php endforeach;?></select><button class="bg-slate-900 text-white px-4 rounded-lg">Filter</button></form><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="text-left p-4">Name</th><th class="text-left p-4">Type</th><th class="text-left p-4">Contact</th><th class="text-left p-4">Currency</th><th class="p-4"></th></tr></thead><tbody class="divide-y"><?php foreach($contacts as $c):?><tr><td class="p-4"><strong><?=h($c['company_name'])?></strong><p class="text-xs text-slate-500"><?=h($c['contact_person'])?></p></td><td class="p-4"><span class="bg-slate-100 px-2.5 py-1 rounded-full text-xs font-bold"><?=h($c['type_name'])?></span></td><td class="p-4"><?=h($c['email']?:'—')?><p class="text-xs text-slate-500"><?=h($c['phone'])?></p></td><td class="p-4 font-semibold"><?=h($c['currency_code'].' '.$c['symbol'])?></td><td class="p-4 text-right"><a href="contacts.php?edit=<?=$c['id']?>" class="brand-text font-semibold">Edit</a></td></tr><?php endforeach;?><?php if(!$contacts):?><tr><td colspan="5" class="p-10 text-center text-slate-500">No contacts found.</td></tr><?php endif;?></tbody></table></div></section></div></div></main><?php require_once 'includes/footer.php';?>
